import "./RouteOverviewFoldToggle.css";

type RouteOverviewFoldKind = "route" | "map";

type RouteOverviewFoldToggleProps = {
  kind: RouteOverviewFoldKind;
  expanded: boolean;
  ariaLabel: string;
  controls?: string;
  className?: string;
  onClick: () => void;
};

/** RouteDock·미니맵이 함께 쓰는 접기 손잡이. 식별 도안과 방향을 한 버튼 안에 둔다. */
export function RouteOverviewFoldToggle({
  kind,
  expanded,
  ariaLabel,
  controls,
  className,
  onClick,
}: RouteOverviewFoldToggleProps) {
  return (
    <button
      type="button"
      className={`route-overview-fold-toggle${className ? ` ${className}` : ""}`}
      data-fold-kind={kind}
      aria-label={ariaLabel}
      aria-expanded={expanded}
      aria-controls={controls}
      onClick={onClick}
    >
      <svg viewBox="0 0 28 20" fill="none" aria-hidden="true">
        <g className="route-overview-fold-toggle__identity">
          {kind === "route" ? (
            <>
              <circle cx="5" cy="6" r="2" />
              <circle cx="5" cy="14" r="2" />
              <path d="M7 6h6M7 14h6" />
            </>
          ) : (
            <path d="M2.5 5.5 7 3.5l4 2 4-2v11l-4 2-4-2-4.5 2zM7 3.5v11M11 5.5v11" />
          )}
        </g>
        <path
          className="route-overview-fold-toggle__chevron"
          d={expanded ? "m23 5-5 5 5 5" : "m18 5 5 5-5 5"}
        />
      </svg>
    </button>
  );
}

.route-overview-fold-toggle {
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  min-width: 28px;
  min-height: 28px;
  padding: 2px;
  border: 1px solid #c9d6ee;
  border-radius: 8px;
  background: #fff;
  color: #475569;
  box-shadow: 0 2px 8px rgba(15, 23, 42, 0.14);
  cursor: pointer;
  touch-action: manipulation;
}

.route-overview-fold-toggle > svg {
  display: block;
  width: 24px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.7;
  stroke-linecap: round;
  stroke-linejoin: round;
  pointer-events: none;
}

.route-overview-fold-toggle:hover {
  border-color: #8da9e4;
  background: #fff;
  color: #1e40af;
}

.route-overview-fold-toggle:focus-visible {
  outline: 2px solid #2457d6;
  outline-offset: 1px;
}

import { useState } from "react";
import type { RideUiStage } from "../../hooks/useRideUiStage";
import {
  isRouteDockActiveRide,
  isRouteDockVisible,
  routeDockDefaultExpanded,
  routeDockUiPolicy,
} from "../../lib/route/routeDockUiPolicy";
import { sensorChipSlot } from "../../lib/route/sensorChipSlot";
import { cadenceChipView } from "../../lib/sensor/cadenceSensorUi";
import { CadenceHudChip, type CadenceChipBinding } from "../maphud/CadenceHudChip";
import type { RouteDockStop, RouteDockStopId } from "./useRouteDockStops";
import "../maphud/CadenceHudChip.css";
import "./RouteDock.css";

export type RouteDockProps = {
  stage: RideUiStage;
  stops: RouteDockStop[];
  routeLoading: boolean;
  onRemoveStop: (id: RouteDockStopId) => void;
  onFocusStop: (stop: RouteDockStop) => void;
  onSwapEndpoints?: () => void;
  editLocked?: boolean;
  cadence?: CadenceChipBinding | null;
  sensorAttention?: boolean;
};

/* 2026-10-24 Chief: 「출발·경유·도착」 글자 대신 지도 핀과 같은 기호 S · 1 2 3 · E(영어로 통일). */
function stopBadge(stop: RouteDockStop): string {
  if (stop.kind === "start") return "S";
  if (stop.kind === "end") return "E";
  return String((stop.waypointIndex ?? 0) + 1);
}

function stopName(stop: RouteDockStop): string {
  if (stop.kind === "start") return "Start";
  if (stop.kind === "end") return "End";
  return `WP${(stop.waypointIndex ?? 0) + 1}`;
}

/* 2026-10-24 Chief 제안 A: 글자 기호(✕ ‹ ›)·CSS 막대 대신 선 1.7 인라인 아이콘. 색은 currentColor. */
function DockIcon({ d, size }: { d: string; size: number }) {
  return (
    <svg
      className="route-dock__icon"
      width={size}
      height={size}
      viewBox="0 0 16 16"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.7}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden
    >
      <path d={d} />
    </svg>
  );
}

const ICON_REMOVE = "M4.5 4.5L11.5 11.5M11.5 4.5L4.5 11.5";
const ICON_SWAP = "M5 13V3M2.5 5.5L5 3L7.5 5.5M11 3V13M8.5 10.5L11 13L13.5 10.5";
const ROUTE_DOCK_PANEL_ID = "route-dock-panel";

/** Addresses (+ sensor chip when expanded). Stays visible during ride; editing locks while riding. */
export function RouteDock({
  stage,
  stops,
  routeLoading,
  onRemoveStop,
  onFocusStop,
  onSwapEndpoints,
  editLocked = false,
  cadence = null,
  sensorAttention = false,
}: RouteDockProps) {
  const [expanded, setExpanded] = useState(() => routeDockDefaultExpanded(stage, stops.length));
  const [prevStage, setPrevStage] = useState(stage);
  const [prevStopCount, setPrevStopCount] = useState(stops.length);
  const { lockStopEditing } = routeDockUiPolicy(stage, editLocked);
  const activeRide = isRouteDockActiveRide(stage);

  /*
   * 주행 시작엔 접고 끝나면 편다. effect 에서 바꾸면 펼친 카드가 한 번 commit 된 뒤 접혀
   * 주행 시작 순간 깜빡였다(감리40 LOW, 10-25 해소) — 렌더 중에 이전 stage 와 비교해 맞춘다.
   * 경로가 생기면 자동 펼침, 삭제되면 LED만.
   */
  if (stage !== prevStage) {
    setPrevStage(stage);
    const wasActive = isRouteDockActiveRide(prevStage);
    const nowActive = isRouteDockActiveRide(stage);
    if (!wasActive && nowActive) {
      setExpanded(false);
    } else if (wasActive && !nowActive) {
      setExpanded(stops.length > 0);
    }
  }
  if (stops.length !== prevStopCount) {
    setPrevStopCount(stops.length);
    if (stops.length > 0 && prevStopCount === 0 && !isRouteDockActiveRide(stage)) {
      setExpanded(true);
    } else if (stops.length === 0 && prevStopCount > 0 && !isRouteDockActiveRide(stage)) {
      setExpanded(false);
    }
  }
  if (!isRouteDockVisible(stage)) return null;
  const sensorInDock =
    sensorChipSlot({ stage, hasCadence: Boolean(cadence), expanded }) === "route-dock";
  // 지시10: 빈 경로에서는 주소 판을 남기지 않는다. 센서가 실제 이 카드에 배치될 때만 예외다.
  if (stops.length === 0 && !sensorInDock) return null;

  const canSwap =
    Boolean(onSwapEndpoints) &&
    !lockStopEditing &&
    stops.some((s) => s.kind === "start") &&
    stops.some((s) => s.kind === "end");
  const sensorChip =
    sensorInDock && expanded && cadence ? (
      <CadenceHudChip
        placement="dock"
        state={cadence.state}
        riding={activeRide}
        open={cadence.open}
        onOpen={cadence.onOpen}
        attention={sensorAttention}
      />
    ) : null;
  const ledConnected = cadence != null && cadenceChipView(cadence.state, false).led === "green";
  const ledToggle = (
    <button
      type="button"
      className={`route-dock__led-toggle${ledConnected ? " route-dock__led-toggle--connected" : ""}`}
      aria-label={expanded ? "경로 패널 접기" : "경로 패널 펼치기"}
      aria-expanded={expanded}
      aria-controls={ROUTE_DOCK_PANEL_ID}
      data-led={ledConnected ? "green" : "white"}
      onClick={() => setExpanded((v) => !v)}
    >
      <span className="route-dock__led" aria-hidden />
    </button>
  );

  return (
    <div
      className={`route-dock-anchor${expanded ? " route-dock-anchor--open" : ""}`}
      aria-label="경로 보기"
      aria-busy={routeLoading}
    >
      <div
        className={`route-dock__card${expanded ? " route-dock__card--head" : " route-dock__card--led"}`}
      >
        {expanded ? (
          <div className="route-dock__head">
            {sensorChip}
            {ledToggle}
          </div>
        ) : (
          ledToggle
        )}
        <div
          id={ROUTE_DOCK_PANEL_ID}
          className={`route-dock__grid${lockStopEditing ? " route-dock__grid--locked" : ""}`}
        >
          <div className="route-dock__stops-wrap">
            <ol className="route-dock__stops" role="list">
              {stops.length === 0 ? (
                <li className="route-dock__stops-empty">지도를 탭해 Start·End 설정</li>
              ) : (
                stops.map((stop) => (
                  <li key={stop.id} className={`route-dock__row route-dock__row--${stop.kind}`}>
                    <button
                      type="button"
                      className="route-dock__stop"
                      onClick={() => onFocusStop(stop)}
                      title="지도에서 보기"
                    >
                      <span
                        className={`route-dock__badge route-dock__badge--${stop.kind}`}
                        aria-label={stopName(stop)}
                      >
                        {stopBadge(stop)}
                      </span>
                      <span className="route-dock__label" title={stop.loading ? undefined : stop.label}>
                        {stop.loading ? "주소 불러오는 중…" : stop.label}
                      </span>
                    </button>
                    {!lockStopEditing ? (
                      <button
                        type="button"
                        className="route-dock__remove"
                        aria-label={`${stopName(stop)} 삭제`}
                        onClick={() => onRemoveStop(stop.id)}
                      >
                        <DockIcon d={ICON_REMOVE} size={11} />
                      </button>
                    ) : null}
                  </li>
                ))
              )}
            </ol>
            {/* 2026-10-24 Chief: ⇅ 는 목록 앞쪽 — 기호 열 위, 목록 세로 가운데(S·E 사이). */}
            {canSwap ? (
              <button
                type="button"
                className="route-dock__swap"
                aria-label="Start·End 바꾸기"
                onClick={onSwapEndpoints}
              >
                <DockIcon d={ICON_SWAP} size={12} />
              </button>
            ) : null}
          </div>
        </div>
      </div>
    </div>
  );
}

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { test, expect, type Page } from '@playwright/test';

const preview = '/scripts/ui-800x360/preview.html';
const evidenceDir = process.env.SENSOR_DOCK_EVIDENCE_DIR
  ?? path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../../document/ops/20261028-sensor-dock/evidence/cursor');
const sizes = [
  { width: 800, height: 360 },
  { width: 736, height: 300 },
  { width: 699, height: 273 },
  { width: 667, height: 300 },
] as const;

async function shot(page: Page, name: string) {
  fs.mkdirSync(evidenceDir, { recursive: true });
  await page.screenshot({ path: path.join(evidenceDir, name), animations: 'disabled' });
}

function led(page: Page) {
  return page.locator('.route-dock__led-toggle');
}
function chip(page: Page) {
  return page.getByRole('button', { name: /^케이던스 센서:/ });
}
function barChip(page: Page) {
  return page.locator('.ride-control-bar .hud-cadence');
}

async function assertLedOnly(page: Page, color: 'white' | 'green') {
  const toggle = led(page);
  await expect(toggle).toBeVisible();
  await expect(toggle).toHaveAttribute('aria-expanded', 'false');
  await expect(toggle).toHaveAttribute('aria-label', '경로 패널 펼치기');
  await expect(toggle).toHaveAttribute('data-led', color);
  await expect(chip(page)).toHaveCount(0);
  await expect(barChip(page)).toHaveCount(0);
  const box = (await toggle.boundingBox())!;
  expect(box.width).toBeGreaterThanOrEqual(28);
  expect(box.height).toBeGreaterThanOrEqual(28);
  expect(box.width).toBeLessThanOrEqual(44);
  expect(box.height).toBeLessThanOrEqual(44);
  const card = (await page.locator('.route-dock__card').boundingBox())!;
  expect(card.width).toBeLessThanOrEqual(44);
  expect(card.height).toBeLessThanOrEqual(44);
}

async function expandAndOpenSheet(page: Page) {
  const expand = page.getByRole('button', { name: '경로 패널 펼치기' });
  if (await expand.isVisible().catch(() => false)) await expand.click();
  await chip(page).click();
  await expect(page.getByRole('dialog', { name: '케이던스 센서', exact: true })).toBeVisible();
}

test.describe('센서 RouteDock 통합', () => {
  test.use({ viewport: { width: 800, height: 360 }, hasTouch: true });

  test('idle LED만 → 펼침 → 센서 시트 → 접기, 주행바와 중복 없음', async ({ page }) => {
    await page.goto(`${preview}?state=idle`);
    await assertLedOnly(page, 'white');
    await expect(page.locator('.ride-control-bar')).toHaveCount(0);
    await expect(page.locator('.route-dock__stops')).toBeHidden();
    await shot(page, 'idle-led-800x360.png');

    await led(page).click();
    await expect(page.locator('.route-dock-anchor--open')).toBeVisible();
    await expect(chip(page)).toHaveCount(1);
    await expect(page.getByText('지도를 탭해 Start·End 설정')).toBeVisible();
    await expect(barChip(page)).toHaveCount(0);

    await chip(page).click();
    const sheet = page.getByRole('dialog', { name: '케이던스 센서', exact: true });
    await expect(sheet).toBeVisible();
    await sheet.getByRole('button', { name: '센서 설정 닫기' }).click();
    await expect(sheet).toBeHidden();

    await page.getByRole('button', { name: '경로 패널 접기' }).click();
    await assertLedOnly(page, 'white');
  });

  test('ready/riding/paused 무중복·펼치면 알약, 접으면 LED만', async ({ page }) => {
    for (const state of ['ready', 'riding', 'paused'] as const) {
      await page.goto(`${preview}?state=${state}`);
      await expect(barChip(page)).toHaveCount(0);
      if (state === 'ready') {
        await expect(page.locator('.route-dock-anchor--open')).toBeVisible();
        await expect(chip(page)).toHaveCount(1);
        await expect(led(page)).toHaveAttribute('aria-expanded', 'true');
        await page.getByRole('button', { name: '경로 패널 접기' }).click();
      } else {
        await expect(page.getByRole('button', { name: '경로 패널 펼치기' })).toBeVisible();
      }
      await assertLedOnly(page, 'white');
      await led(page).click();
      await expect(chip(page)).toHaveCount(1);
      await expect(barChip(page)).toHaveCount(0);
      if (state === 'riding') await expect(page.getByRole('button', { name: '일시정지' })).toBeVisible();
      if (state === 'paused') await expect(page.getByRole('button', { name: '재개' })).toBeVisible();
    }
  });

  test('실제 연결만 녹색, 체험 속도는 흰색, 재연결 후 녹색', async ({ page }) => {
    await page.goto(`${preview}?state=idle`);
    await assertLedOnly(page, 'white');

    await page.goto(`${preview}?state=sensor-connected`);
    await page.getByRole('button', { name: '센서 설정 닫기' }).click();
    await expect(chip(page)).toHaveCount(1);
    await page.getByRole('button', { name: '경로 패널 접기' }).click();
    await assertLedOnly(page, 'green');
    await shot(page, 'idle-led-connected-800x360.png');

    const sheet = page.getByRole('dialog', { name: '케이던스 센서', exact: true });
    await expandAndOpenSheet(page);
    await sheet.getByRole('button', { name: '연결 해제', exact: true }).click();
    await sheet.getByRole('button', { name: '센서 설정 닫기' }).click();
    await page.getByRole('button', { name: '경로 패널 접기' }).click();
    await assertLedOnly(page, 'white');

    await page.goto(`${preview}?state=sensor-connected`);
    await page.getByRole('button', { name: '센서 설정 닫기' }).click();
    await page.getByRole('button', { name: '경로 패널 접기' }).click();
    await assertLedOnly(page, 'green');

    await page.goto(`${preview}?state=sensor-riding-manual`);
    await expect(page.locator('.audit-world')).toHaveAttribute('data-ui-stage', 'riding');
    await page.getByRole('button', { name: '센서 설정 닫기' }).click();
    await assertLedOnly(page, 'white');
  });

  test('경로 생김 자동펼침·삭제 후 LED·단일 Start·주행 접힘/종료 펼침', async ({ page }) => {
    await page.goto(`${preview}?state=idle`);
    await assertLedOnly(page, 'white');

    await page.goto(`${preview}?state=setup`);
    await expect(page.locator('.route-dock-anchor--open')).toBeVisible();
    await expect(page.locator('.route-dock__badge--start')).toHaveText('S');
    await expect(chip(page)).toHaveCount(1);

    await page.goto(`${preview}?state=ready`);
    await expect(page.locator('.route-dock-anchor--open')).toBeVisible();
    await page.getByRole('button', { name: '주행 시작', exact: true }).click();
    await expect(page.getByRole('button', { name: '경로 패널 펼치기' })).toBeVisible();
    await expect(chip(page)).toHaveCount(0);
    await page.getByRole('button', { name: '일시정지', exact: true }).click();
    await expect(page.getByRole('button', { name: '경로 패널 펼치기' })).toBeVisible();
    await led(page).click();
    await expect(chip(page)).toHaveCount(1);
    await page.getByRole('button', { name: '재개', exact: true }).click();
    await expect(page.locator('.route-dock-anchor--open')).toBeVisible();
    await page.getByRole('button', { name: '주행 종료', exact: true }).click();
    await page.keyboard.press('Escape');
    await expect(page.getByRole('button', { name: '경로 패널 펼치기' })).toBeVisible();
    await expect(page.locator('.ride-control-bar')).toHaveCount(0);
  });

  test('키보드 Enter/Space와 reduced-motion', async ({ page }) => {
    await page.goto(`${preview}?state=idle`);
    await led(page).focus();
    await page.keyboard.press('Enter');
    await expect(page.locator('.route-dock-anchor--open')).toBeVisible();
    await page.getByRole('button', { name: '경로 패널 접기' }).focus();
    await page.keyboard.press('Space');
    await expect(page.getByRole('button', { name: '경로 패널 펼치기' })).toBeVisible();

    await page.emulateMedia({ reducedMotion: 'reduce' });
    await page.goto(`${preview}?state=idle`);
    const animation = await page.locator('.route-dock__led').evaluate((el) => getComputedStyle(el).animationName);
    expect(animation === 'none' || animation === '').toBeTruthy();
  });

  for (const size of sizes) {
    test(`${size.width}×${size.height} 경계 — idle LED·ready 알약·riding 접힘`, async ({ page }) => {
      await page.setViewportSize(size);
      await page.goto(`${preview}?state=idle`);
      await assertLedOnly(page, 'white');
      const idleLed = (await led(page).boundingBox())!;
      expect(idleLed.x).toBeGreaterThanOrEqual(0);
      expect(idleLed.y + idleLed.height).toBeLessThanOrEqual(size.height + 1);

      await page.goto(`${preview}?state=ready`);
      await expect(chip(page)).toHaveCount(1);
      const readyChip = (await chip(page).boundingBox())!;
      expect(readyChip.x + readyChip.width).toBeLessThanOrEqual(size.width + 1);
      expect(readyChip.height).toBeGreaterThanOrEqual(28);

      await page.goto(`${preview}?state=riding`);
      await assertLedOnly(page, 'white');
      await led(page).click();
      await expect(chip(page)).toHaveCount(1);
      await shot(page, `riding-expanded-${size.width}x${size.height}.png`);
    });
  }
});

/* White route card — 폭은 주행 중 미니맵과 같은 29.4vw(MINIMAP_WIDTH_RATIO, 2026-10-24 Chief);
 * 대기 화면은 센서·접기가 맨 위 한 줄. */
.route-dock-anchor {
  --route-dock-pad: clamp(.45rem, 1.4vw, .85rem);
  position: absolute;
  left: max(48px, calc(env(safe-area-inset-left, 0px) + 48px)); /* 반달 핸들44px + 여백4px(MapBottomLeftStack과 동일) */
  bottom: calc(max(var(--route-dock-pad), env(safe-area-inset-bottom, 0px)) + var(--mapbox-logo-clearance, 2.875rem));
  width: min(29.4vw, calc(100vw - 16px));
  z-index: 6;
  pointer-events: none;
}
.route-dock__card {
  position: relative;
  pointer-events: auto;
  box-sizing: border-box;
  padding: 6px 8px 8px 12px;
  border-radius: 12px;
  background: #fff;
  color: #121417;
  box-shadow: 0 6px 24px rgba(0, 0, 0, 0.28);
}
.route-dock-anchor:not(.route-dock-anchor--open) {
  width: auto;
}
.route-dock-anchor:not(.route-dock-anchor--open) .route-dock__grid {
  display: none;
}
.route-dock-anchor:not(.route-dock-anchor--open) .route-dock__card {
  width: 28px;
  height: 28px;
  min-width: 28px;
  padding: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
/* 맨 위 줄: 접기 LED(왼쪽) · 센서 알약. */
.route-dock__head {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  min-height: 30px;
  padding-left: 32px;
  margin-bottom: 2px;
}
.route-dock-anchor--open .route-dock__card--head { padding-top: 3px; }

  justify-content: center;
}
.route-dock__icon { display: block; flex: 0 0 auto; pointer-events: none; }
