    <div
      className={`route-dock-anchor${expanded ? " route-dock-anchor--open" : ""}`}
      aria-label="경로 보기"
      aria-busy={routeLoading}
    >
      <div
        className={`route-dock__card${expanded ? " route-dock__card--head" : " route-dock__card--led"}`}
      >
        {expanded ? (
          <div className="route-dock__head">
            {sensorChip}
            {ledToggle}
          </div>
        ) : (
          ledToggle
        )}
